<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>2048</title>
<style>
body{background:#0f0f1a;color:#e0e0e0;font-family:system-ui,sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0}
#container{text-align:center}
h1{margin:0 0 10px}
#scoreboard{display:flex;gap:12px;justify-content:center;align-items:center;margin-bottom:12px}
#score{font-size:20px;font-weight:bold}
#reset{padding:8px 16px;font-size:16px;cursor:pointer;border:none;border-radius:6px;background:#4a4a6a;color:#fff}
#board{width:420px;height:420px;display:grid;grid-template-columns:repeat(4,1fr);gap:12px;background:#1e1e2f;padding:12px;border-radius:12px;margin:0 auto}
.cell{background:#2a2a3e;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:32px;font-weight:bold}
</style>
</head>
<body>
<div id="container">
<h1>2048</h1>
<div id="scoreboard">
<div id="score">Score: 0</div>
<button id="reset">New Game</button>
</div>
<div id="board"></div>
</div>
<script>
const size = 4;
let board = [];
let scoreVal = 0;

function initBoard(){ board = Array(size).fill().map(()=>Array(size).fill(0)); }

function getColor(v){
  const map={2:'#eee4da',4:'#ede0c8',8:'#f2b179',16:'#f59563',32:'#f67c5f',64:'#f65e3b',128:'#edcf72',256:'#edcc61',512:'#edc850',1024:'#edc53f',2048:'#edc22e'};
  return map[v]||'#3c3a32';
}

function render(){
  const el=document.getElementById('board');
  el.innerHTML='';
  for(let r=0;r<size;r++){
    for(let c=0;c<size;c++){
      const cell=document.createElement('div');
      cell.className='cell';
      const v=board[r][c];
      if(v!==0){
        cell.textContent=v;
        cell.style.background=getColor(v);
        cell.style.color=v<8?'#000':'#fff';
      }
      el.appendChild(cell);
    }
  }
  document.getElementById('score').textContent='Score: '+scoreVal;
}

function addRandomTile(){
  const empties=[];
  for(let r=0;r<size;r++)for(let c=0;c<size;c++)if(board[r][c]===0)empties.push([r,c]);
  if(!empties.length)return;
  const [r,c]=empties[Math.floor(Math.random()*empties.length)];
  board[r][c]=Math.random()<0.9?2:4;
}

function processLine(line){
  const filtered=line.filter(v=>v!==0);
  const newLine=[];
  let scoreAdd=0;
  let i=0;
  while(i<filtered.length){
    if(i+1<filtered.length && filtered[i]===filtered[i+1]){
      const merged=filtered[i]*2;
      newLine.push(merged);
      scoreAdd+=merged;
      i+=2;
    }else{
      newLine.push(filtered[i]);
      i+=1;
    }
  }
  while(newLine.length<size)newLine.push(0);
  const changed=line.some((v,idx)=>v!==newLine[idx]);
  return {newLine,scoreAdd,changed};
}

function move(dir){
  let moved=false;
  let scoreAddTotal=0;
  const newBoard=board.map(r=>[...r]);
  if(dir==='left'||dir==='right'){
    for(let r=0;r<size;r++){
      let line=board[r].slice();
      if(dir==='right')line.reverse();
      const {newLine,scoreAdd,changed}=processLine(line);
      const finalLine=dir==='right'?newLine.reverse():newLine;
      if(changed)moved=true;
      scoreAddTotal+=scoreAdd;
      for(let c=0;c<size;c++)newBoard[r][c]=finalLine[c];
    }
  }else{
    for(let c=0;c<size;c++){
      let line=[];
      for(let r=0;r<size;r++)line.push(board[r][c]);
      if(dir==='down')line.reverse();
      const {newLine,scoreAdd,changed}=processLine(line);
      const finalLine=dir==='down'?newLine.reverse():newLine;
      if(changed)moved=true;
      scoreAddTotal+=scoreAdd;
      for(let r=0;r<size;r++)newBoard[r][c]=finalLine[r];
    }
  }
  if(moved){
    scoreVal+=scoreAddTotal;
    board=newBoard;
    addRandomTile();
    render();
  }
  return moved;
}

function reset(){
  scoreVal=0;
  initBoard();
  addRandomTile();
  addRandomTile();
  render();
}

function setBoard(arr){
  if(!Array.isArray(arr)||arr.length!==size)return;
  initBoard();
  for(let r=0;r<size;r++){
    if(!Array.isArray(arr[r])||arr[r].length!==size)continue;
    for(let c=0;c<size;c++)board[r][c]=arr[r][c]||0;
  }
  render();
}

function getBoard(){ return board.map(r=>[...r]); }
function getScore(){ return scoreVal; }

window.game={
  size,
  reset,
  move,
  board:getBoard,
  setBoard,
  score:getScore
};

document.getElementById('reset').addEventListener('click',reset);
window.addEventListener('keydown',e=>{
  const map={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'};
  if(map[e.key]){e.preventDefault();move(map[e.key]);}
});

reset();
</script>
</body>
</html>
